// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {airPort} from "../src/airPort.sol";

contract InvMutTest is Test {
    airPort c;
    // helper to act as the callee that records calls to transferFrom
    Recorder rec;

    function setUp() public { 
        c = new airPort();
        rec = new Recorder();
    }

    // fuzz the from address, a recipient address, a value, and the array length (keeps wide)
    function testFuzz_property(address from, address to, uint256 v, uint256 len) public {
        // keep len small but allow zero to be filtered by require in C
        uint256 l = bound(len, 0, 4);

        // build dynamic array of recipients of length l
        address[] memory tos = new address[](l);
        for (uint i = 0; i < l; i++) {
            // alternate between the recorder and the provided `to` so calls land on a contract that records
            tos[i] = (i % 2 == 0) ? address(rec) : to;
        }

        // The contract C requires _tos.length > 0; when l == 0 the call will revert in both versions.
        // We observe only non-reverting executions: use try/catch to detect success.
        bool ok;
        try c.transfer(from, address(rec), tos, v) returns (bool ret) {
            ok = true;
            // The reference implementation always returns true when it completes successfully.
            // We assert that the return value is true by observing the call's returned value via the try return value.
            // However the test must make a single assertTrue over c's observable behavior. To satisfy the
            // harness rules, we set a local flag and assertTrue over the universal property below.
            // But since try/catch gives us `ret`, we use it to set recordedReturn flag in recorder.
            rec.recordReturn(ret);
        } catch {
            ok = false;
            // record a false to keep recorder state consistent
            rec.recordReturn(false);
        }

        // The universal property: for any admissible input, if transfer completes (ok == true) then it returns true.
        // We read that fact from the recorder which stored the return value observed by this test.
        // Retrieve the recorded return value for this invocation
        bool observedReturn = rec.lastReturn();

        // If the call reverted (ok == false), the universal property is vacuously true; we only assert when ok == true.
        if (ok) {
            assertTrue(observedReturn);
        } else {
            // when it reverted, nothing to assert; still assertTrue(true) is not allowed, so assert that address(c) is unchanged
            // We must make exactly one assertTrue in the test; above branch executes when ok==true. To ensure solidity
            // compiles with single assert in all paths, we simply return here.
            return;
        }
    }
}

// Recorder contract to observe calls made by C. It also stores the last return value recorded by the test's try/catch.
contract Recorder {
    // store number of calls received and last decoded args
    uint256 public callCount;
    address[] public tosRecorded;
    mapping(uint256 => CallInfo) public calls;

    struct CallInfo {
        address from;
        address to;
        uint256 value;
    }

    // the function signature that C encodes: transferFrom(address,address,uint256)
    function transferFrom(address from, address to, uint256 value) external returns (bool) {
        calls[callCount] = CallInfo(from, to, value);
        callCount++;
        return true; // succeed by default
    }

    // storage for last return value observed by the test harness via recordReturn
    bool private _lastReturn;
    function recordReturn(bool r) external {
        _lastReturn = r;
    }
    function lastReturn() external view returns (bool) {
        return _lastReturn;
    }
}
